// ⚙️ CONFIGURACIÓN - CAMBIAR AQUÍ
const SEND_EMAILS = "true";  // "true" para enviar, "false" solo mostrar
const TARGET_EMAIL = "agustin.sodire@gmail.com";
const DELAY_SECONDS = 2;

const items = $input.all();

return items.map(item => ({
  json: {
    ...item.json,
    config: {
      sendEmails: SEND_EMAILS === "true",
      targetEmail: TARGET_EMAIL,
      delaySeconds: DELAY_SECONDS
    }
  }
}));

