const items = $input.all();

const stats = {
  client: 0,
  billing: 0,
  lead: 0,
  internal: 0,
  spam: 0
};

let sent = 0;
let notSent = 0;

items.forEach(item => {
  if (stats[item.json.category] !== undefined) {
    stats[item.json.category]++;
  }

  // Check if email was sent
  if (item.json.config && item.json.config.sendEmails) {
    sent++;
  } else {
    notSent++;
  }
});

let summary = '\n╔═══════════════════════════════════════╗\n';
summary += '║  📧 GENERADOR DE EMAILS - REPORTE   ║\n';
summary += '╚═══════════════════════════════════════╝\n\n';
summary += `Total generados: ${items.length} emails\n`;
summary += `✅ Enviados: ${sent}\n`;
summary += `⏸️  No enviados: ${notSent}\n\n`;
summary += '── Por categoría ──────────────────────\n';
summary += `🔵 CLIENTE:   ${stats.client}\n`;
summary += `💰 FACTURAS:  ${stats.billing}\n`;
summary += `🟢 LEAD:      ${stats.lead}\n`;
summary += `🟡 INTERNO:   ${stats.internal}\n`;
summary += `🔴 SPAM:      ${stats.spam}\n`;
summary += '\n' + '═'.repeat(40) + '\n';

if (sent > 0 && items[0].json.config) {
  summary += `\n📬 Emails enviados a: ${items[0].json.config.targetEmail}\n`;
  summary += `⏱️  Delay entre envíos: ${items[0].json.config.delaySeconds}s\n`;
}

console.log(summary);

return [{
  json: {
    total: items.length,
    sent: sent,
    notSent: notSent,
    stats: stats,
    summary: summary,
    config: items[0]?.json?.config || null,
    emails: items.map(i => i.json)
  }
}];
